};

/**
 * @event
 * @name scwin.noticeTable_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.noticeTable_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_noticeList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'noticeTable.fillAct' });
    }
};

/**
 * @method
 * @name scwin.detail
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_sprtRoomNo index init
 * @returns
 * @hidden N
*/
scwin.detail = async function (ipt_sprtRoomNo, index, init) {
    /* sdd-asis-lifecycle:begin fn_detail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#searchForm')).val(ipt_sprtRoomNo);
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods25010/jldods25010.xml");
    $('#ipt_method', $('#searchForm')).val("readNoticeDetail");
    await scwin.tx_fn_detail();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setInqCnt
 * @author Inswave
 * @date 2026. 09. 29
 * @param inqCnt
 * @returns
 * @hidden N
*/
scwin.setInqCnt = function (inqCnt) {
    /* sdd-asis-lifecycle:begin setInqCnt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#inqCnt' + scwin.mainIndex).html(inqCnt);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_pageIndex
 * @returns
 * @hidden N
*/
scwin.search = async function (ipt_pageIndex) {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await alertE("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await alertE("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await alertE("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods25000/jldods25000.xml");
    $('#ipt_method', $('#searchForm')).val("readNoticeList");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param sprt_room_no attach_seq attach_file_nm
 * @returns
 * @hidden N
*/
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    /* sdd-asis-lifecycle:begin fn_fileDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods25000/jldods25000.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }


/**
 * @event
 * @name scwin.krxpage_pagenavigator_89_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_89_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.search(); };
